    Object.assign(WORDS, ETO_EGYPTIAN_EXPANSION_V2.words);

    if(typeof PHRASES !== 'undefined' && Array.isArray(PHRASES)){
        ETO_EGYPTIAN_EXPANSION_V2.phrases.slice().reverse().forEach(pair => {
            PHRASES.unshift(pair);
        });
    }

    if(typeof PATTERN_RULES !== 'undefined' && Array.isArray(PATTERN_RULES)){
        ETO_EGYPTIAN_EXPANSION_V2.patterns.forEach(pair => {
            try{
                PATTERN_RULES.push([new RegExp(pair[0],'gi'),pair[1]]);
            }catch(error){
                console.warn('[Eto Egyptian DB] Invalid pattern:',pair[0],error);
            }
        });
    }

    Object.keys(ETO_EGYPTIAN_EXPANSION_V2.technicalWords || {}).forEach(key => {
        WORDS[key] = ETO_EGYPTIAN_EXPANSION_V2.technicalWords[key];
    });

    function normalizeArabic(text){
        return String(text || '')
            .replace(/[\u064B-\u065F\u0670]/g,'')
            .replace(/[إأآا]/g,'ا')
            .replace(/ى/g,'ي')
            .replace(/ؤ/g,'و')
            .replace(/ئ/g,'ي')
            .replace(/ة/g,'ه')
            .replace(/ـ/g,'')
            .replace(/\s+/g,' ')
            .trim();
    }

    function escapeRegExp(text){
        return String(text).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
    }

    function phraseReplace(text){
        let value = String(text || '');

        const phrases = [...PHRASES].sort((a,b)=>b[0].length-a[0].length);
        for(const [from,to] of phrases){
            value = value.replace(new RegExp(escapeRegExp(from),'gi'),to);
        }

        const entries = Object.entries(WORDS)
            .sort((a,b)=>b[0].length-a[0].length);

        for(const [from,to] of entries){
            const pattern = new RegExp('(^|[^\u0621-\u064A])' + escapeRegExp(from) + '([^\u0621-\u064A]|$)','gi');
            value = value.replace(pattern, '$1' + to + '$2');
        }

        for(const [pattern,to] of PATTERN_RULES){
            value = value.replace(pattern,to);
        }

        return value;
    }

    function cleanupArabic(text){
        let value = String(text || '')
            .replace(/\s+([،؛,:.!؟])/g,'$1')
            .replace(/([،؛,:.!؟])(?=[^\s])/g,'$1 ')
            .replace(/\s{2,}/g,' ')
            .trim();

        value = value
            .replace(/\bده دي\b/g,'دي')
            .replace(/\bهو هو\b/g,'هو')
            .replace(/\bهي هي\b/g,'هي')
            .replace(/\bممكن ممكن\b/g,'ممكن')
            .replace(/\bبرضه برضه\b/g,'برضه')
            .replace(/\bبس بس\b/g,'بس')
            .replace(/\bأوي أوي\b/g,'أوي');

        return value;
    }

    function protectTechnicalTerms(text){
        const saved = [];
        let value = String(text || '');

        for(const term of KEEP_AS_IS){
            const pattern = new RegExp(escapeRegExp(term),'g');
            value = value.replace(pattern, m => {
                const token = '__ETO_KEEP_' + saved.length + '__';
                saved.push([token,m]);
                return token;
            });
        }

        return {text:value,saved};
    }

    function restoreTechnicalTerms(text,saved){
        let value = String(text || '');
        for(const [token,original] of saved){
            value = value.replace(new RegExp(escapeRegExp(token),'g'),original);
        }
        return value;
    }

    function egyptianize(text){
        if(!text) return '';

        const protectedValue = protectTechnicalTerms(String(text).trim());
        let value = protectedValue.text;

        value = phraseReplace(value);
        value = cleanupArabic(value);
        value = restoreTechnicalTerms(value,protectedValue.saved);

        return value;
    }

    function getDictionary(){
        return {
            words: WORDS,
            phrases: PHRASES,
            patterns: PATTERN_RULES,
            keepAsIs: Array.from(KEEP_AS_IS)
        };
    }

    window.EtoEgyptianTranslationData = {
        version: '2026-09-25-v1',
        wordCount: Object.keys(WORDS).length,
        phraseCount: PHRASES.length,
        patternCount: PATTERN_RULES.length,
        egyptianize,
        getDictionary
    };

